"use client";

import { FormEvent, useState } from "react";
import { supabase } from "@/lib/supabaseClient";

async function getDeviceId(): Promise<string> {
  if (typeof window === "undefined") return "";
  let id = localStorage.getItem("gather_device_id");
  if (!id) {
    id = crypto.randomUUID();
    localStorage.setItem("gather_device_id", id);
  }
  return id;
}

export default function CreateEventPage() {
  const [name, setName] = useState("");
  const [joinPin, setJoinPin] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);

  const generatePin = () => {
    return Math.floor(100000 + Math.random() * 900000).toString();
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!name.trim()) {
      setError("Donne un nom à ton évènement.");
      return;
    }

    const pin = generatePin();
    setCreating(true);

    try {
      // --- Récupération optionnelle de l'utilisateur (anonyme autorisé) ---
      let userId: string | null = null;
      try {
        const { data: authInfo } = await supabase.auth.getUser();
        userId = authInfo?.user?.id ?? null;
      } catch (authError) {
        console.warn(
          "Aucune session Supabase, création d'évènement anonyme.",
          authError,
        );
      }

      const deviceId = await getDeviceId();

      const { error: insertError } = await supabase.from("events").insert({
        name: name.trim(),
        pin,
        host_device_id: deviceId,
        host_user_id: userId, // peut être null pour le MVP
      });

      if (insertError) {
        console.error(insertError);
        setError("Erreur lors de la création de l'évènement.");
        setCreating(false);
        return;
      }

      // On connaît déjà le PIN → redirection directe
      window.location.href = `/events/${pin}`;
    } catch (err) {
      console.error(err);
      setError("Erreur inattendue.");
      setCreating(false);
    }
  };

  const handleJoin = (e: FormEvent) => {
    e.preventDefault();
    if (!joinPin.trim()) {
      setError("Entre un PIN pour rejoindre un coffre.");
      return;
    }
    window.location.href = `/events/${joinPin.trim()}`;
  };

  return (
    <main className="min-h-screen flex items-center justify-center bg-slate-950 text-white px-4">
      <div className="w-full max-w-5xl rounded-3xl bg-slate-900/80 border border-slate-800 px-6 py-8 md:px-12 md:py-10 shadow-xl flex flex-col md:flex-row gap-8">
        {/* Bloc gauche : branding / pitch */}
        <div className="flex-1 flex flex-col justify-between gap-6">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-slate-800 flex items-center justify-center">
              <img
                src="/gather-logo.png"
                alt="Logo Gather"
                className="h-8 w-8 object-contain"
              />
            </div>
            <div className="text-xs uppercase tracking-[0.2em] text-slate-400">
              GATHER-MVP
              <span className="ml-2 text-[0.7rem] text-slate-500">
                Coffres photo partagés
              </span>
            </div>
          </div>

          <div className="space-y-4">
            <h1 className="text-3xl md:text-4xl font-semibold leading-tight">
              Crée un <span className="text-teal-400">coffre photo</span>{" "}
              éphémère pour ton groupe.
            </h1>
            <p className="text-sm md:text-base text-slate-300 max-w-md">
              Un évènement = un PIN + un QR code. Tout le monde peut déposer
              ses photos dans le même coffre, sans compte, en quelques secondes.
            </p>
          </div>

          <p className="text-xs text-slate-500 max-w-sm">
            Pensé pour les voyages, mariages, soirées et moments de vie que tu
            veux rassembler au même endroit.
          </p>
        </div>

        {/* Bloc droit : création / join */}
        <div className="flex-1 bg-slate-900 rounded-2xl border border-slate-800 px-6 py-6 flex flex-col gap-5">
          <div className="text-xs uppercase tracking-[0.2em] text-slate-400 mb-1">
            Nouveau coffre
          </div>
          <h2 className="text-lg font-semibold text-slate-100">
            Créer un évènement
          </h2>
          <p className="text-xs text-slate-400 mb-2">
            Donne un nom à ton évènement, on génère le PIN pour toi.
          </p>

          <form onSubmit={handleSubmit} className="space-y-3">
            <div className="space-y-1">
              <label
                htmlFor="event-name"
                className="text-xs font-medium text-slate-300"
              >
                Nom de l&apos;évènement
              </label>
              <input
                id="event-name"
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full rounded-xl bg-slate-900 border border-slate-700 px-3 py-2 text-sm text-white outline-none focus:border-teal-400 focus:ring-2 focus:ring-teal-500/30"
                placeholder="Anniv Léa & Karim, Soirée Fête, etc."
              />
            </div>

            {error && (
              <p className="text-xs text-red-400 mt-1">{error}</p>
            )}

            <button
              type="submit"
              disabled={creating}
              className="w-full rounded-xl bg-teal-500 hover:bg-teal-400 disabled:opacity-60 disabled:hover:bg-teal-500 transition-colors text-sm font-semibold py-2.5 mt-1"
            >
              {creating ? "Création en cours..." : "Créer l'évènement"}
            </button>
          </form>

          <div className="border-t border-slate-800 my-4" />

          <form
            onSubmit={handleJoin}
            className="flex flex-col gap-3 text-sm"
          >
            <span className="text-xs text-slate-400">
              Tu as déjà un PIN ?{" "}
              <span className="text-slate-200 font-medium">
                Rejoindre un coffre existant
              </span>
            </span>

            <div className="flex gap-2">
              <input
                type="text"
                value={joinPin}
                onChange={(e) => setJoinPin(e.target.value)}
                className="flex-1 rounded-xl bg-slate-900 border border-slate-700 px-3 py-2 text-sm text-white outline-none focus:border-teal-400 focus:ring-2 focus:ring-teal-500/30"
                placeholder="Entre le PIN"
              />
              <button
                type="submit"
                className="rounded-xl bg-slate-800 hover:bg-slate-700 transition-colors text-xs px-3 font-medium"
              >
                Rejoindre
              </button>
            </div>
          </form>

          <div className="mt-4 text-xs text-slate-400">
            <button
              type="button"
              className="inline-flex items-center gap-2 text-slate-300 hover:text-white transition-colors"
            >
              Participer à l&apos;aventure Gather 🚀
            </button>
          </div>
        </div>
      </div>
    </main>
  );
}
